function normalize(value) {
  if (Array.isArray(value)) return value.map(normalize);
  if (!value || typeof value !== "object") return value;
  return Object.keys(value).sort().reduce((out, key) => {
    out[key] = normalize(value[key]);
    return out;
  }, {});
}

function sameValue(a, b) {
  if (a !== null && a !== undefined && a !== "" && b !== null && b !== undefined && b !== "") {
    if (Number.isFinite(Number(a)) && Number.isFinite(Number(b))) {
      return Math.abs(Number(a) - Number(b)) <= 0.000001;
    }
  }
  return JSON.stringify(normalize(a)) === JSON.stringify(normalize(b));
}

function isEntityNotFoundError(error) {
  const status = Number(error?.status || error?.response?.status || error?.response?.statusCode || error?.data?.status || 0);
  if (status === 404) return true;
  const message = String(
    error?.message ||
    error?.response?.data?.message ||
    error?.response?.data?.error ||
    error?.data?.message ||
    error?.data?.error ||
    ""
  ).toLowerCase();
  return message.includes("not found") || message.includes("does not exist");
}

export function expectedBuilderEntityFields(record = {}, nextFields = {}) {
  return Object.fromEntries(
    Object.keys(nextFields || {}).map((field) => [field, record?.[field]])
  );
}

export async function replaceBuilderEntityFieldsIfUnchanged({
  entity,
  id,
  expectedUpdatedAt = "",
  expectedFields,
  nextFields,
  guardFields = {},
  label = "Builder record",
  maxAttempts = 3,
} = {}) {
  const recordId = String(id || "").trim();
  const expectedVersion = String(expectedUpdatedAt || "").trim();
  const expected = expectedFields && typeof expectedFields === "object" && !Array.isArray(expectedFields) ? expectedFields : null;
  const desired = nextFields && typeof nextFields === "object" && !Array.isArray(nextFields) ? nextFields : null;
  const guards = guardFields && typeof guardFields === "object" && !Array.isArray(guardFields) ? guardFields : {};
  const fieldNames = desired ? Object.keys(desired) : [];
  if (!recordId || !expected || !desired || fieldNames.length === 0 || typeof entity?.get !== "function" || typeof entity?.updateMany !== "function") {
    throw new Error(`${label} could not initialize its concurrency-safe update.`);
  }
  for (const fieldName of fieldNames) {
    if (!Object.prototype.hasOwnProperty.call(expected, fieldName)) {
      throw new Error(`${label} is missing the loaded baseline for ${fieldName}.`);
    }
  }

  const attempts = Math.max(1, Math.min(5, Number(maxAttempts) || 3));
  for (let attempt = 0; attempt < attempts; attempt += 1) {
    const current = await entity.get(recordId);
    if (!current?.id) throw new Error(`${label} could not be re-read before saving.`);

    for (const [fieldName, value] of Object.entries(guards)) {
      if (!sameValue(current[fieldName], value)) {
        throw new Error(`${label} changed in another session (${fieldName}). Reload before saving.`);
      }
    }

    const alreadyDesired = fieldNames.every((fieldName) => sameValue(current[fieldName], desired[fieldName]));
    if (alreadyDesired) return current;

    if (expectedVersion && String(current.updated_date || "") !== expectedVersion) {
      throw new Error(`${label} changed in another session. Reload before saving.`);
    }

    for (const fieldName of fieldNames) {
      if (!sameValue(current[fieldName], expected[fieldName]) && !sameValue(current[fieldName], desired[fieldName])) {
        throw new Error(`${label} changed in another session (${fieldName}). Reload before saving.`);
      }
    }

    const currentVersion = String(current.updated_date || "").trim();
    if (!currentVersion) throw new Error(`${label} is missing its current version. Reload before saving.`);

    let result;
    try {
      result = await entity.updateMany(
        { id: recordId, updated_date: currentVersion },
        { $set: desired },
      );
    } catch (error) {
      const afterError = await entity.get(recordId).catch(() => null);
      if (afterError && fieldNames.every((fieldName) => sameValue(afterError[fieldName], desired[fieldName]))) return afterError;
      throw error;
    }

    if (!result || typeof result.updated !== "number") {
      throw new Error(`${label} conditional-update result could not be verified.`);
    }
    if (result.updated === 1) {
      const saved = await entity.get(recordId).catch(() => null);
      if (!saved) throw new Error(`${label} was updated but could not be re-read.`);
      return saved;
    }
  }

  throw new Error(`${label} changed repeatedly while saving. Reload and try again.`);
}

export async function deleteBuilderEntityIfUnchanged({
  entity,
  record,
  guardFields = {},
  label = "Builder record",
} = {}) {
  const id = String(record?.id || "").trim();
  const updatedDate = String(record?.updated_date || "").trim();
  if (!id || !updatedDate || typeof entity?.deleteMany !== "function" || typeof entity?.get !== "function") {
    throw new Error(`${label} could not initialize its concurrency-safe delete.`);
  }
  // Caller guards can narrow the match further but must never widen it past
  // the loaded id + updated_date anchor, so they are spread first.
  const query = { ...guardFields, id, updated_date: updatedDate };
  let result;
  try {
    result = await entity.deleteMany(query);
  } catch (error) {
    let current;
    try {
      current = await entity.get(id);
    } catch (verificationError) {
      if (isEntityNotFoundError(verificationError)) {
        return { deleted: true, convergedAfterResponseLoss: true };
      }
      throw new Error(
        `${label} delete returned an error and its outcome could not be verified. ` +
        `Do not retry blindly; reload before continuing. ${verificationError?.message || ""}`.trim()
      );
    }
    if (!current) return { deleted: true, convergedAfterResponseLoss: true };
    throw error;
  }
  if (!result || typeof result.deleted !== "number") {
    throw new Error(`${label} conditional-delete result could not be verified.`);
  }
  if (result.deleted === 1) return { deleted: true };
  if (result.deleted > 1) {
    throw new Error(`${label} returned an impossible multi-record delete count.`);
  }
  let current;
  try {
    current = await entity.get(id);
  } catch (verificationError) {
    if (isEntityNotFoundError(verificationError)) {
      return { deleted: true, alreadyDeleted: true };
    }
    throw new Error(
      `${label} deletion matched no current version and the record could not be re-read. ` +
      `Do not retry blindly; reload before continuing. ${verificationError?.message || ""}`.trim()
    );
  }
  if (!current) return { deleted: true, alreadyDeleted: true };
  throw new Error(`${label} changed in another session. It was not deleted.`);
}

// Generic aliases let other estimator records reuse the same proven conditional
// persistence behavior without introducing a second concurrency implementation.
export const expectedEntityFields = expectedBuilderEntityFields;
export const replaceEntityFieldsIfUnchanged = replaceBuilderEntityFieldsIfUnchanged;
export const deleteEntityIfUnchanged = deleteBuilderEntityIfUnchanged;

import { deleteEntityIfUnchanged } from "@/components/estimator/builder/builderEntityPersistence";
import { base44 } from "@/api/base44Client";

function normalize(value) {
  if (Array.isArray(value)) return value.map(normalize);
  if (!value || typeof value !== "object") return value;
  return Object.keys(value).sort().reduce((out, key) => {
    out[key] = normalize(value[key]);
    return out;
  }, {});
}

function sameValue(a, b) {
  if (a !== null && a !== undefined && a !== "" && b !== null && b !== undefined && b !== "") {
    if (Number.isFinite(Number(a)) && Number.isFinite(Number(b))) {
      return Math.abs(Number(a) - Number(b)) <= 0.000001;
    }
  }
  return JSON.stringify(normalize(a)) === JSON.stringify(normalize(b));
}

function matchesPayload(row = {}, payload = {}) {
  return Object.entries(payload || {}).every(([field, value]) => sameValue(row?.[field], value));
}

export async function createInventoryRecordWithRecovery({
  entity,
  data = {},
  nameField,
  label = "Inventory item",
} = {}) {
  const field = String(nameField || "").trim();
  const name = String(data?.[field] ?? "").trim();
  if (!field || !name || typeof entity?.filter !== "function" || typeof entity?.create !== "function") {
    throw new Error(`${label} could not initialize its retry-safe create.`);
  }

  const readCandidates = async () => {
    const rows = await entity.filter({ [field]: data[field] });
    if (!Array.isArray(rows)) throw new Error(`${label} lookup did not return a record list.`);
    return rows;
  };

  const before = await readCandidates();
  const beforeIds = new Set(before.map((row) => row?.id).filter(Boolean));

  let created = null;
  let createError = null;
  try {
    created = await entity.create(data);
  } catch (error) {
    createError = error;
  }

  if (created?.id) {
    const verified = typeof entity.get === "function" ? await entity.get(created.id).catch(() => null) : null;
    if (verified?.id && !matchesPayload(verified, data)) {
      throw new Error(`${label} was created but its stored values do not match this save. Reload the inventory and review the new row before retrying.`);
    }
    return { record: verified?.id ? verified : created, status: "created" };
  }

  const after = await readCandidates();
  const newExactMatches = after.filter((row) => !beforeIds.has(row?.id) && matchesPayload(row, data));
  if (newExactMatches.length === 1) {
    return { record: newExactMatches[0], status: "recovered" };
  }
  if (newExactMatches.length > 1) {
    throw new Error(`${label} may have been created more than once while the create response was unavailable. No inventory rows were deleted; reload and review the new matching rows before retrying.`);
  }

  if (createError) throw createError;
  throw new Error(`${label} could not verify whether it was created. Reload the inventory before retrying.`);
}

export async function deleteInventoryRecordIfUnchanged({
  entity,
  record,
  nameField,
  label = "Inventory item",
} = {}) {
  const field = String(nameField || "").trim();
  const guardFields = field && Object.prototype.hasOwnProperty.call(record || {}, field)
    ? { [field]: record[field] }
    : {};
  return deleteEntityIfUnchanged({
    entity,
    record,
    guardFields,
    label,
  });
}

// Cascade-check before inventory delete: estimate Parts link to inventory rows
// via inventory_item_id. Deleting a referenced row would orphan those links, so
// callers must run this first and block the delete when references exist.
export async function findInventoryPartReferences(recordId) {
  const id = String(recordId || "");
  if (!id || typeof base44?.entities?.BuilderPart?.filter !== "function") {
    throw new Error("Estimate Part references could not be verified.");
  }
  const rows = await base44.entities.BuilderPart.filter({ inventory_item_id: id });
  const list = Array.isArray(rows) ? rows : [];
  return {
    count: list.length,
    names: list.map((p) => p.part_name || p.part_key || "Part").slice(0, 5),
  };
}

// Usage history: resolve estimate Parts → BuilderProducts → distinct estimates
// so inventory rows can show a "used in N estimates" badge. Sequential product
// reads are bounded by how many products consume the item.
export async function findInventoryEstimateUsage(recordId) {
  const id = String(recordId || "");
  if (!id || typeof base44?.entities?.BuilderPart?.filter !== "function" || typeof base44?.entities?.BuilderProduct?.get !== "function") {
    throw new Error("Estimate usage could not be verified.");
  }
  const rows = await base44.entities.BuilderPart.filter({ inventory_item_id: id });
  const parts = Array.isArray(rows) ? rows : [];
  const productIds = [...new Set(parts.map((p) => p?.builder_product_id).filter(Boolean))];
  const estimateIds = new Set();
  for (const productId of productIds) {
    const product = await base44.entities.BuilderProduct.get(productId).catch(() => null);
    if (product?.estimate_id) estimateIds.add(product.estimate_id);
  }
  return { parts: parts.length, products: productIds.length, estimates: estimateIds.size, estimateIds: [...estimateIds].slice(0, 25) };
}

const COST_FIELD_RX = /cost|rate|price/i;

// Writes InventoryCostHistory rows for any cost/rate/price-named field whose
// value changed between the loaded row and the saved payload. Best-effort:
// failures are swallowed so the audit never blocks an inventory save.
export async function recordInventoryCostChanges({ itemId, entityKey, before = {}, after = {}, fields = [], note = "Inventory edit", changedBy = "" } = {}) {
  if (!itemId || typeof base44?.entities?.InventoryCostHistory?.create !== "function") return 0;
  const costFields = new Set((fields || []).filter((f) => f?.name && COST_FIELD_RX.test(f.name)).map((f) => f.name));
  const candidates = new Set([...costFields, ...Object.keys(after).filter((k) => COST_FIELD_RX.test(k))]);
  let written = 0;
  for (const field of candidates) {
    const oldVal = Number(before[field]);
    const newVal = Number(after[field]);
    if (!Number.isFinite(oldVal) || !Number.isFinite(newVal) || Math.abs(oldVal - newVal) <= 0.000001) continue;
    await base44.entities.InventoryCostHistory.create({
      inventory_item_id: String(itemId),
      entity_key: String(entityKey || ""),
      cost_field: String(field),
      old_cost: oldVal,
      new_cost: newVal,
      changed_by: String(changedBy || ""),
      note: String(note || ""),
    }).catch(() => { /* audit must not fail the save */ });
    written += 1;
  }
  return written;
}

export async function loadInventoryCostHistory({ itemId, entityKey = "", limit = 5 } = {}) {
  if (!itemId || typeof base44?.entities?.InventoryCostHistory?.filter !== "function") return [];
  const query = entityKey
    ? { inventory_item_id: String(itemId), entity_key: String(entityKey) }
    : { inventory_item_id: String(itemId) };
  const rows = await base44.entities.InventoryCostHistory.filter(query).catch(() => []);
  const list = Array.isArray(rows) ? rows : [];
  return list
    .sort((a, b) => String(b?.created_date || "").localeCompare(String(a?.created_date || "")))
    .slice(0, limit);
}
